style.css:
@-moz-document domain("web.whatsapp.com") {
:root {
    --kali-bg: #0d0f14;
    --kali-bg-alt: #1a1d26;
    --kali-fg: #d6dbe5;
    --kali-white: #ffffff;
    --kali-dim: #6c7385;
    --kali-green: #2fd36f;
    --kali-blue: #3b8eea;
    --kali-red: #ff4c4c;
    --kali-border: #23272f;
  }

  /* Base */
  html, body, #app, #app * {
    font-family: "Fira Code", "Hack", "JetBrains Mono", "Cascadia Mono", "Consolas", monospace !important;
    color: var(--kali-fg) !important;
    border-radius: 0 !important;
    box-shadow: none !important;
    text-shadow: none !important;
  }

  html, body, #app, #side, #pane-side, #main, header, footer {
    background-color: var(--kali-bg) !important;
  }

  /* Papel de parede */
  #app div, #app span {
    background-image: none !important;
  }

  /* Baloes transparentes */
  [role="row"], [role="row"] * {
    background-color: transparent !important;
  }

  /* Topo da lista com prompt */
  #side header:before {
    content: "\250C \2500 \2500 (kali\327F whatsapp)-[~/conversas]\A\2514 \2500 $ ls -la";
    white-space: pre;
    display: block;
    padding: 8px 12px;
    font-size: 12px;
    line-height: 1.5;
    color: var(--kali-green) !important;
  }

  /* Lista de conversas */
  #pane-side img {
    display: none !important;
  }

  #pane-side span[title] {
    color: var(--kali-blue) !important;
    font-weight: 600 !important;
  }

  #pane-side span[title]:before {
    content: "drwxr-xr-x  ";
    color: var(--kali-dim) !important;
    font-weight: 400 !important;
  }

  #pane-side [role="row"]:hover,
  #pane-side [role="row"]:hover * {
    background-color: var(--kali-bg-alt) !important;
  }

  #pane-side [aria-selected="true"],
  #pane-side [aria-selected="true"] * {
    background-color: var(--kali-blue) !important;
    color: var(--kali-white) !important;
  }

  #pane-side [aria-selected="true"] span[title],
  #pane-side [aria-selected="true"] span[title]:before {
    color: var(--kali-white) !important;
  }

  /* Prefixo de log nas mensagens */
  [data-pre-plain-text]:before {
    content: attr(data-pre-plain-text);
    color: var(--kali-dim) !important;
  }

  /* Rabinho e tiques */
  [data-icon*="tail"],
  [data-icon^="msg-check"],
  [data-icon^="msg-dblcheck"] {
    display: none !important;
  }

  /* Icones */
  #app svg, #app svg * {
    fill: var(--kali-dim) !important;
  }

  /* Campo de digitacao */
  footer [contenteditable="true"] {
    caret-color: var(--kali-white) !important;
    color: var(--kali-white) !important;
  }

  footer [contenteditable="true"]:before {
    content: "\2514 \2500 $ ";
    color: var(--kali-blue) !important;
    font-weight: 700 !important;
  }

  ::selection {
    background: var(--kali-blue) !important;
    color: var(--kali-white) !important;
  }
}
